insert into public.cargos (id, nome, funcao, salario, status) values
(4, 'ADMINISTRATIVO DE OBRAS', 'ORGANIZAR TODOS OS DOCUMENTOS DE UMA RESPECTIVA OBRA E DE SEUS FUNCIONARIOS. FAZER FECHAMENTO MENSAL D0S APONTAMENTOS DIARIOS DE TODOS OS FUNCIONARIOS. ORGANIZAR AS REPUBLICAS. EMISSA0 DE RELATORIOS EXIGIDOS PELO CLIENTE. ABRIR E MANTER CONVENIOS COM O COMERCIO DA REGIAO EM GERAL. EFETUAR PAGAMENTOS A TERCEIROS. FAZER ADMISSAO E DEMISSAO DE FUNCIONARIOS.', 7.34, 'ativo'),
(5, 'ELETROMECANICO MONTADOR ESPECIALIZADO I', 'MONTAGEM DE LEITO E ELETROCALHAS. FIXACAO DE LUMINARIAS, EQUIPAMENTOS E INSTRUMENTOS. USO DE FERRAMENTAS ELETRO-PORTATEIS. LANCAMENTO DE CABOS ELETRICOS. AJUSTES DE CHAVES DE DESALINHAMENTO.', 6.44, 'ativo'),
(6, 'AJUDANTE GERAL', 'AUXILIO NAS ATIVIDADES ELETRO-MECANICAS EM GERAL', 4.35, 'ativo'),
(7, 'ZELADORA / DOMESTICA / FAXINEIRA', 'LIMPEZA, ARRUMACAO DOMESTICA EM GERAL E LAVAGEM DE ROUPAS.', 3.6, 'ativo'),
(8, 'ELETRICISTA FORCA E CONTROLE', 'LIGACAO ELETRICA, LANCAMENTO DE CABOS ELETRICOS E MONTAGEM FISICA DE QUADROS E PAINEIS DESENERGIZADOS. MONTAGEM ELETROMECANICA EM GERAL.', 7.98, 'ativo'),
(9, 'MEIO OFICIAL ELETROMECANICO', 'MONTAGEM DE ELETRODUTOS. FABRICACAO DE SUPORTES METALICOS PARA ELETRODUTOS. SOLDA ELETRICA. CORTE DE INSERTES METALICOS COM POLICORTE. USO DE FERRAMENTAS ELETRO-PORTATEIS. LANCAMENTO DE CABOS ELETRICOS.', 4.64, 'ativo'),
(12, 'ENGENHEIRO COORDENADOR DE OBRAS', 'SUPERVISAO E COORDENACAO DE TODAS AS ATIVIDADES ADMINISTRATIVAS E DE TODOS OS SERVICOS RELACIONADOS A EXECUCAO DE MONTAGEM ELETRICA NAS OBRAS CONFORME PROJETO DO CLIENTE. PARTICIPACAO NAS REUNIOES COM OS CLIENTES.', 7880.0, 'ativo'),
(13, 'SUPERVISOR DE MONTAGEM', 'SUPERVISIONAR A EXECUCAO DOS SERVICOS DE MONTAGEM ELETRICA NAS OBRAS CONFORME PROJETOS DO CLIENTE.', 16.05, 'ativo'),
(14, 'ENCARREGADO DE MONTAGEM', 'COMANDAR E ACOMPANHAR A EXECUCAO DOS SERVICOS DE MONTAGEM ELETRICA NAS OBRAS CONFORME PROJETOS DO CLIENTE. EMITIR RELATORIOS DE PRODUCAO DOS SERVICOS QUE ESTAO SENDO EXECUTADOS. ACOMPANHAR OS FUNCIONARIOS ASSEGURANDO QUE OS PROCEDIMENTOS E NORMAS DE SEGURANCA ESTEJAM SENDO CUMPRIDOS.', 17.75, 'ativo'),
(15, 'ENCARREGADO II', 'ACOMPANHAR A EXECUCAO DOS SERVICOS DE MONTAGEM ELETRICA NAS OBRAS CONFORME PROJETOS DO CLIENTE. EMITIR RELATORIOS DE PRODUCAO DOS SERVICOS QUE ESTAO SENDO EXECUTADOS. ACOMPANHAR OS FUNCIONARIOS ASSEGURANDO QUE OS PROCEDIMENTOS E NORMAS DE SEGURANCA ESTEJAM SENDO CUMPRIDOS.', 15.36, 'ativo'),
(16, 'ENCARREGADO I', 'EMITIR RELATORIOS DE PRODUCAO DOS SERVICOS QUE ESTAO SENDO EXECUTADOS E ACOMPANHAR OS FUNCIONARIOS ASSEGURANDO QUE OS PROCEDIMENTOS E NORMAS DE SEGURANCA ESTEJAM SENDO CUMPRIDAS.', 13.84, 'ativo'),
(17, 'LIDER DE ELETRICA', 'ACOMPANHAR OS FUNCIONARIOS ASSEGURANDO QUE OS PROCEDIMENTOS E NORMAS DE SEGURANCA ESTEJAM SENDO CUMPRIDAS. APLICAR TESTES COM HI-POT.', 11.07, 'ativo'),
(18, 'ELETROMECANICO LIDER', 'ACOMPANHAR OS FUNCIONARIOS ASSEGURANDO QUE OS PROCEDIMENTOS E NORMAS DE SEGURANCA ESTEJAM SENDO CUMPRIDAS.', 10.45, 'ativo'),
