(82, 'ALMOXARIFE SENIOR', 'CONTROLE DE RECEBIMENTOS E ENTREGA DE MATERIAIS. CONTROLE DE ESTOQUE DE MATERIAIS. REPOSICAO DE ESTOQUE DE MATERIAIS. COTACAO, EQUALIZACAO DE PRECOS E COMPRA DE MATERIAIS. INSPECAO DE MATERIAIS. INVENTARIO PERIODICO DE MATERIAIS E FERRAMENTAS. CONTROLE DE BENS PATRIMONIAIS. REQUISICAO DE MATERIAIS.', 7.98, 'ativo'),
(83, 'ENFERMEIRA PADRAO', 'EDUCACAO OCUPACIONAL, CONTROLE E REGISTRO DA PRESSAO ARTERIAL E BAFOMETRO.', 5.9, 'desativado'),
(84, 'SUPERVISOR ADMINISTRATIVO I', 'SUPERVISIONAR TODA A AREA ADMINISTRATIVA NAS OBRAS, INCLUINDO: ADMINISTRACAO, PLANEJAMENTO, ALMOXARIFADO E TRANSPORTES.', 12.7, 'ativo'),
(85, 'MOTORISTA E OPERADOR DE MUNCK II', 'MOTORISTA E OPERACAO DE GUINDAUTO (MUNCK). CONDUCAO E OPERACAO DE VEICULOS EM GERAL NO INTERIOR DAS FABRICAS E NO TRAJETO. TRANSPORTE DE FUNCIONARIOS VIA ONIBUS PARA DIVERSAS LOCALIDADES ONDE A EMPRESA EXECUTA SEUS SERVICOS. CHECK-LIST DOS VEICULOS.', 7.79, 'ativo'),
(86, 'TECNICO ELETROTECNICO I', 'INSTRUTOR DO CURSO BASICO NR-10: SEGURANCA EM INSTALACOES E SERVICOS COM ELETRICIDADE. CONTROLE DE AFERICAO E CALIBRACAO DOS EQUIPAMENTOS ELETRO-ELETRONICOS. MONTAGEM ELETRO-MECANICA. AUXILIAR NAS COMPRAS E CONTROLES DE EQUIPAMENTOS E FERRAMENTAS ELETRO-PORTATEIS.', 7.3, 'ativo'),
(87, 'SERRALHEIRO E SOLDADOR SENIOR', 'FABRICACAO DE SUPORTES METALICOS PARA FIXACAO DE ELETRODUTOS, ETC. FABRICACAO DE PECAS METALICAS PARA MONTAGEM ELETRICA. SOLDA ELETRICA. CORTE COM APARELHO OXI-ACETILENICO. USO DE EQUIPAMENTOS ELETRICOS PORTATEIS.', 8.21, 'ativo'),
(88, 'TECNICO EM ENFERMAGEM', 'EDUCACAO OCUPACIONAL, CONTROLE E REGISTRO DA PRESSAO ARTERIAL E BAFOMETRO.', 5.33, 'ativo'),
(89, 'TECNICO DE SEGURANCA DO TRABALHO PLENO', 'SUPERVISIONAR E ACOMPANHAR A EXECUCAO DAS ATIVIDADES DE LIGACAO / MONTAGEM ELETRICA E SEUS RESPECTIVOS RISCOS DE ACIDENTES VERIFICANCO SE ESTAO SENDO EXECUTADOS DE ACORDO COM PROCEDIMENTOS E NRS. FAZER O CONTROLE DO FORNECIMENTO DE EPIS E UNIFORMES. ANALISAR OS RISCOS DOS LOCAIS DE TRABALHO E INFORMAR OS FUNCIONARIOS QUANTO AOS RISCOS PERTINENTES AS SUAS ATIVIDADES E AREAS DE TRABALHO. MINISTRAR TREINAMENTOS DE SEGURANCA DO TRABALHO. ELABORACAO, DIVULGACAO E ACOMPANHAMENTO DOS SEGUINTES PROGRAMAS PPRA, LTCAT, PCMAT, PCMSO. MONTAGEM DE CIPA. TRATAR OS INCIDENTES PRESTAR PRIMEIROS SOCORROS. FAZER COMUNICACAO DOS ACIDENTES DE TRABALHO. INFORMAR DADOS PARA ELABORACAO DA ESTATISTICA MENSAL DE ACIDENTES.', 10.04, 'ativo'),
(90, 'ENFERMEIRA', 'EDUCACAO OCUPACIONAL, CONTROLE E REGISTRO DA PRESSAO ARTERIAL E BAFOMETRO.', 5.9, 'ativo'),
(91, 'MOTORISTA ADMINISTRATIVO', 'MOTORISTA', 6.65, 'ativo'),
(92, 'ELETRICISTA DE CABLAGEM I', 'LANCAMENTO DE CABOS ELETRICOS. MONTAGEM DE ELETRODUTOS. FABRICACAO DE SUPORTES METALICOS PARA ELETRODUTOS. SOLDA ELETRICA. CORTE DE INSERTES METALICOS COM POLICORTE. USO DE FERRAMENTAS ELETRO-PORTATEIS.', 6.44, 'ativo'),
(93, 'MEIO OFICIAL PINTOR', 'LIXAR, LIMPAR E PINTAR SUPORTES EM GERAL', 4.64, 'ativo'),
(94, 'ENGENHEIRO ELETRICISTA TREINEE', 'FAZ PARTE DE UM PROGRAMA ESTRUTURADO DA EMPRESA PARA QUE EM UM PERIODO CURTO DE TEMPO ADQUIRA A AMBIENTACAO CULTURAL E PERFIL QUE A EMPRESA NECESSITA.PARTICIPA DO GRUPO TECNICO DA EMPRESA, AUXILIANDO EM DUVIDAS RELACIONADAS AO PROJETO E A EXECUCAO. TAMBEM AUXILIA NA GESTAO ADMINISTRATIVA DA OBRA. POSSUI FORMACAO TECNICA NA AREA PREDOMINANTE DA EMPRESA, MAS DESENVOLVERA ATRIBUTOS NECESSARIOS PARA ATENDER A TODOS OUTROS DEPARTAMENTOS INTERNOS.', 4728.0, 'ativo'),
(95, 'AJUDANTE DE PINTOR INDUSTRIAL', 'LIXAMENTO, LIMPEZA E PREPARACAO DE PECAS E ESTRUTURAS METALICAS, ORGANIZACAO E LIMPEZA DA AREA DE TRABALHO, SINALIZACAO E DELIMITACAO DA AREA DE TRABALHO. AUXILIO NECESSARIO EM TODAS AS TIVIDADES DESENVOLVIDAS NA OFICINA DE PINTURA.', 4.35, 'ativo'),
(96, 'TECNICO DE SEGURANCA DO TRABALHO SENIOR', 'SUPERVISIONAR E ACOMPANHAR A EXECUCAO DAS ATIVIDADES DE LIGACAO / MONTAGEM ELETRICA E SEUS RESPECTIVOS RISCOS DE ACIDENTES VERIFICANCO SE ESTAO SENDO EXECUTADOS DE ACORDO COM PROCEDIMENTOS E NRS. FAZER O CONTROLE DO FORNECIMENTO DE EPIS E UNIFORMES. ANALISAR OS RISCOS DOS LOCAIS DE TRABALHO E INFORMAR OS FUNCIONARIOS QUANTO AOS RISCOS PERTINENTES AS SUAS ATIVIDADES E AREAS DE TRABALHO. MINISTRAR TREINAMENTOS DE SEGURANCA DO TRABALHO. ELABORACAO, DIVULGACAO E ACOMPANHAMENTO DOS SEGUINTES PROGRAMAS PPRA, LTCAT, PCMAT, PCMSO. MONTAGEM DE CIPA. TRATAR OS INCIDENTES PRESTAR PRIMEIROS SOCORROS. FAZER COMUNICACAO DOS ACIDENTES DE TRABALHO. INFORMAR DADOS PARA ELABORACAO DA ESTATISTICA MENSAL DE ACIDENTES.', 9.16, 'ativo'),
(97, 'MONTADOR DE ANDAIME', 'TRANSPORTE DE ANDAIMES, MONTAGEM DE PECAS DE ANDAIMES', 6.7, 'ativo'),
(98, 'MONTADOR DE ANDAIME LIDER', 'A COLOCAR', 10.04, 'ativo'),
(99, 'LIDER DE ALMOXARIFADO E SUPRIMENTOS', null, 10.45, 'ativo');

